/**
 * A New Decree
 * ------------
 * The king gives Haman's house to Esther and Mordecai, and a new decree lets the Jews defend themselves. Stage: the royal gate at dawn, a new seal on a fresh scroll, riders lining up; light breaking over the city; a relieved crowd at the gates.
 *
 * Palette 0x1a2a14 → 0x060402 · light: ember · hero: scroll
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./esther-kit.js.
 */

import { THREE, createScene, cityGate, house, column, throne, scroll, person, crowd } from './esther-kit.js';

const BG = 0x1a2a14;
const GROUND = 0x060402;

export function build(group) {
    const W = createScene(group, { seed: 390897811, bg: BG, fogNear: 45, fogFar: 180 });

    /* light — ember */
    W.lights({ sky: 0x3a2418, gnd: 0x1a0e08, hemi: 0.4, sun: 0xff7a30, sunI: 0.7, sunPos: [20, 26, 30] });

    W.stars(90, 150, [0xf0e0c8, 0xd8c0a0], 0.7);
    W.disc([0, 34, -150], 14, 0xff8a30, 0.12);

    /* ground */
    W.ground(260, 260, 0, 0, 0x060402, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* city: gate, towers and houses on the far side */
    const city = W.grp(group, [-11, 0, -58], { name: 'city', r: [0, -0.14, 0] });
    cityGate(W, city, 0, 0, 0, 1.15, { stone: 0x060402, trim: 0x050302 });
    for (let i = 0; i < 5; i++) {
        house(W, city, -34 + i * 17 + W.rr(-4, 4), 0, W.rr(-14, 6), 0.85 + W.r() * 0.4, { mud: 0x060402 });
    }
    W.backdrop(city);

    /* palace: columns, banners and the throne */
    for (let i = -2; i <= 2; i++) column(W, group, i * 8, 0, -30, 11, 1.3, 0x060402, { band: 0x14200f });
    throne(W, group, 0, 0, -24, 1.4, { gold: 0x111b0d });

    /* hero: the scroll */
    scroll(W, group, 0, 0.9, 0, 1.2, { ry: 0.5 });
    W.disc([0, 4, -10], 4, 0x22371a, 0.3);

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0xe8dcc0, head: 'crown', collar: 0xe0b040, ry: 0.36, s: 1.04 });
    person(W, group, [4.5, 0, 6], { robe: 0xe8dcc0, head: 'crown', collar: 0xe0b040, ry: 0.06, s: 1.15 });
    /* crowd: the people of the story */
    crowd(W, group, 0, 16, 22, 70, 44, [0x1a2a14, 0x060402, 0x8a6a44, 0x6a4a30, 0xc8b088, 0x5a4a6a]);

    return W.finish();
}

export default { build };
